diff --git a/mailnews/protocols/ews/test/unit/test_ewsAttachmentSaves.js b/mailnews/protocols/ews/test/unit/test_ewsAttachmentSaves.js
new file mode 100644
index 00000000000..f517b2ccf23
--- /dev/null
+++ b/mailnews/protocols/ews/test/unit/test_ewsAttachmentSaves.js
@@ -0,0 +1,171 @@
+/* This Source Code Form is subject to the terms of the Mozilla Public
